-- =====================================================================
--  05_farmacias_gcba_completo.sql
--  Padron completo de farmacias de CABA (Buenos Aires Data, GCBA,
--  dataset "farmacias", licencia CC-BY-2.5-AR): 1240 registros.
--  Ejecutar DESPUES de 03 y 04. No borra nada: agrega las farmacias que no
--  esten ya cargadas (misma ubicacion a menos de ~30 m), stock de prueba
--  aleatorio y un Operador ACTIVO por farmacia sin operador
--  (operador.f<ID>@medlink.test / Password123!, SOLO demo local).
-- =====================================================================
BEGIN;

CREATE TEMP TABLE gcba_farmacia (
    nombre VARCHAR(120), direccion VARCHAR(200), telefono VARCHAR(30),
    latitud NUMERIC(10,7), longitud NUMERIC(10,7)
) ON COMMIT DROP;


SELECT setval(pg_get_serial_sequence('farmacia', 'id_farmacia'), (SELECT max(id_farmacia) FROM farmacia));

SELECT DISTINCT ON (g.latitud, g.longitud) g.nombre, g.direccion, g.telefono, g.latitud, g.longitud, 'ACTIVA'
FROM gcba_farmacia g
WHERE NOT EXISTS (
    SELECT 1 FROM farmacia f
    WHERE f.latitud IS NOT NULL
      AND abs(f.latitud - g.latitud) < 0.0003 AND abs(f.longitud - g.longitud) < 0.0003)
ORDER BY g.latitud, g.longitud, g.nombre;

-- Stock de prueba reproducible para farmacias sin stock (~45% de las presentaciones activas).
SELECT setseed(0.42);
SELECT f.id_farmacia, p.id_presentacion, 1 + floor(random() * 30)::int,
       now() - make_interval(days => floor(random() * 7)::int)
FROM farmacia f
CROSS JOIN presentacion_medicamento p
WHERE p.estado = 'ACTIVA'
  AND NOT EXISTS (SELECT 1 FROM stock s WHERE s.id_farmacia = f.id_farmacia)
  AND random() < 0.45
ORDER BY f.id_farmacia, p.id_presentacion;

-- Un Operador ACTIVO por cada farmacia que no tenga ninguno.
SELECT setval(pg_get_serial_sequence('cuenta', 'id_cuenta'), (SELECT max(id_cuenta) FROM cuenta));
SELECT setval(pg_get_serial_sequence('operador', 'id_operador'), (SELECT max(id_operador) FROM operador));

WITH h AS (SELECT crypt('Password123!', gen_salt('bf', 10)) AS hash),
nuevas AS (
    SELECT 'operador.f' || f.id_farmacia || '@medlink.test', h.hash, 'OPERADOR', 'ACTIVA', now()
    FROM farmacia f CROSS JOIN h
    WHERE f.estado = 'ACTIVA'
      AND NOT EXISTS (SELECT 1 FROM operador o JOIN cuenta c ON c.id_cuenta = o.id_cuenta
                      WHERE o.id_farmacia = f.id_farmacia AND c.estado = 'ACTIVA')
    ORDER BY f.id_farmacia
    RETURNING id_cuenta, correo
)
SELECT n.id_cuenta,
       substring(n.correo FROM 'operador\.f([0-9]+)@')::bigint,
       'Operador',
       'Farmacia ' || substring(n.correo FROM 'operador\.f([0-9]+)@')
FROM nuevas n;

COMMIT;
ANALYZE;
